// El frontend envía: { nombre, email, telefono, franja, edad, motivacion,
// resumen, bloques, foto_antes, origen, fecha }. Este email es el aviso
// INMEDIATO al negocio en cuanto el lead deja sus datos de contacto —
// a propósito NO incluye el informe (resumen/bloques/foto_despues): eso
// es para el propio usuario, no para este correo. Si además completa el
// formulario de cualificación, llega un SEGUNDO email aparte con esas
// respuestas (ver workflow "Landing IA — Cualificación").
//
// Se queda foto_antes como adjunto (la foto que subió el lead) porque
// ayuda a identificar al cliente, no porque sea parte del informe.

const body = $input.first().json.body || $input.first().json;

const binary = {};
if (body.foto_antes) {
  binary.foto_antes = await this.helpers.prepareBinaryData(
    Buffer.from(body.foto_antes, 'base64'), 'antes.jpg', 'image/jpeg'
  );
}

return [{
  json: {
    nombre: body.nombre || '',
    email: body.email || '',
    telefono: body.telefono || '',
    franja: body.franja || '',
    edad: body.edad || '',
    motivacion: body.motivacion || '',
    origen: body.origen || '',
    fecha: body.fecha || '',
  },
  binary,
}];

